/*
System:   boot                      Phase: frame
Job:      Leave the boot screen once the game font and the sprites are ready (Design §13.3,
          Impl §5.8, §5.9, §9.3). A sprite that fails to load stops the game, naming the sprite.
          Interim (Plan M04, until M23): it then starts a game straight away, with the dev
          `?seed` and `?difficulty` query parameters (Impl §10).
Reads:    app.screen, app.platform.fontReady, app.platform.spritesReady, settings.lastDifficulty
Writes:   app.platform.fontReady, app.platform.spritesReady, app.screen, app.screenTime,
          world (newWorld), rng (newWorld)
Emits:    —
Consumes: —
Guard:    app.screen == 'boot', a resource became ready, or loading a sprite failed
*/
import type { Platform } from '../../host/platform';
import type { Difficulty } from '../../model/state/settings';
import { newWorld } from '../../model/worldOps';
import type { System } from '../../scheduler/system';

/** What the loading promises reported; a fresh object per `init`, so a late promise can't leak. */
interface Loading {
  font: boolean;
  sprites: boolean;
  spriteError: Error | null;
}

const idle = (): Loading => ({ font: false, sprites: false, spriteError: null });

const DIFFICULTIES: readonly string[] = ['easy', 'normal', 'hard'] satisfies Difficulty[];

/** A fresh unpredictable game seed (Impl §4.1), or the dev `?seed=<uint>` (Impl §10). */
function gameSeed(platform: Platform | null): number {
  const param = import.meta.env.DEV ? platform?.query('seed') : null;
  if (param != null && /^\d+$/.test(param)) return Number(param) >>> 0;
  return (Date.now() ^ (performance.now() * 1000)) >>> 0;
}

/** The dev `?difficulty=easy|normal|hard` (Impl §10), or the last one played. */
function gameDifficulty(platform: Platform | null, last: Difficulty): Difficulty {
  const param = import.meta.env.DEV ? platform?.query('difficulty') : null;
  return param != null && DIFFICULTIES.includes(param) ? (param as Difficulty) : last;
}

export function createBoot(): System {
  let loading = idle();
  let platform: Platform | null = null;

  return {
    name: 'boot',
    phase: 'frame',
    init(_state, host) {
      const current = idle();
      loading = current;
      platform = host.platform;
      void host.platform.fonts.ready().then(() => {
        current.font = true;
      });
      host.sprites.load().then(
        () => {
          current.sprites = true;
        },
        (err: unknown) => {
          current.spriteError = err instanceof Error ? err : new Error(String(err));
        },
      );
    },
    update(state) {
      const { app } = state;
      // Thrown here, the scheduler's fail-fast path shows the message (Impl §3.5).
      if (loading.spriteError !== null) throw loading.spriteError;
      if (loading.font) app.platform.fontReady = true;
      if (loading.sprites) app.platform.spritesReady = true;
      if (app.screen !== 'boot' || !app.platform.fontReady || !app.platform.spritesReady) return;
      newWorld(state, {
        seed: gameSeed(platform),
        difficulty: gameDifficulty(platform, state.settings.lastDifficulty),
        demo: false,
        startWave: 1,
      });
      app.screen = 'playing';
      app.screenTime = 0;
    },
    dispose() {
      loading = idle();
      platform = null;
    },
  };
}
