/*
System:   inputMapper               Phase: input
Job:      Merge the input devices into held actions and latched presses (Design §9.1, §9.6,
          Impl §6.4). Keyboard only for now.
Reads:    input.devices.keyboard, settings.keyBindings
Writes:   input.held, input.latched
Emits:    —
Consumes: —
Guard:    none (always runs)
*/
import type { Action } from '../../config/keys';
import type { System } from '../../scheduler/system';

export function createInputMapper(): System {
  return {
    name: 'inputMapper',
    phase: 'input',
    init() {
      // No platform resources.
    },
    update(state) {
      const { input, settings } = state;
      const { down, pressed } = input.devices.keyboard;
      const codes = (action: Action) =>
        settings.keyBindings[action].filter((code) => code !== null);
      const isHeld = (action: Action) => codes(action).some((code) => down.has(code));
      const wasPressed = (action: Action) => codes(action).some((code) => pressed.includes(code));

      // The keyboard's climb/dive and left/right count as −1/+1 (Design §9.6). Left/right use
      // directional flight (Design §9.5): the ship turns to face the way it is flown.
      input.held.vertical = (isHeld('dive') ? 1 : 0) - (isHeld('climb') ? 1 : 0);
      input.held.horizontal = (isHeld('right') ? 1 : 0) - (isHeld('left') ? 1 : 0);
      input.held.thrust = false;
      input.held.fire = isHeld('fire');

      // A press stays latched until the next tick takes it (Design §9.6).
      const { latched } = input;
      if (wasPressed('fire')) latched.fire = true;
      if (wasPressed('smartBomb')) latched.smartBomb = true;
      if (wasPressed('hyperspace')) latched.hyperspace = true;
    },
    dispose() {
      // Nothing to release.
    },
  };
}
