import { DT } from '../config/constants';
import type { Host } from '../host/host';
import type { GameState } from '../model/state/gameState';
import type { System, SystemFactory } from './system';

/** Seconds per tick (Design §4.1). */
export { DT };
/** The most game time one frame may catch up (Design §4.1). */
export const MAX_FRAME_SECONDS = 0.25;
export const MAX_TICKS_PER_FRAME = 8;

/** The systems to run, per phase, in execution order (Code §8.1). */
export interface SystemLists {
  input: readonly SystemFactory[];
  tick: readonly SystemFactory[];
  frame: readonly SystemFactory[];
}

export interface Scheduler {
  /** Inits every system in registry order, then runs a frame per animation frame. */
  start(state: GameState): void;
  /** Stops the loop and disposes every system in reverse order. */
  stop(): void;
}

/**
 * The fixed-step loop of Code §8.2 (Impl §3.5). It also implements `host.control`.
 * `requestFrame` schedules the next frame; tests pass a manual one.
 */
export function createScheduler(
  host: Host,
  lists: SystemLists,
  requestFrame: (cb: () => void) => void = (cb) => requestAnimationFrame(cb),
): Scheduler {
  const input = lists.input.map((create) => create());
  const tick = lists.tick.map((create) => create());
  const frame = lists.frame.map((create) => create());
  const all = [...input, ...tick, ...frame];

  let state: GameState | null = null;
  let pending: GameState | null = null;
  let running = false;
  let lastNow = 0;
  let startNow = 0;
  let accumulator = 0;

  host.control = {
    replaceState: (next) => {
      pending = next;
    },
    stop,
  };

  function start(initial: GameState) {
    state = initial;
    startNow = lastNow = host.clock.now();
    accumulator = 0;
    running = true;
    if (initAll(initial)) requestFrame(loop);
  }

  function stop() {
    if (!running) return;
    running = false;
    for (const system of [...all].reverse()) {
      try {
        system.dispose();
      } catch (err) {
        host.log.error(`[system ${system.name}] dispose`, err);
      }
    }
  }

  function loop() {
    runFrame();
    if (running) requestFrame(loop);
  }

  function runFrame() {
    if (!running) return;
    if (pending) {
      const next = pending;
      pending = null;
      for (const system of [...all].reverse())
        guard(system, 'dispose', () => {
          system.dispose();
        });
      state = next;
      if (!initAll(next)) return;
    }
    const s = state;
    if (!s) return;

    const now = host.clock.now();
    s.time.frameDt = Math.min(now - lastNow, MAX_FRAME_SECONDS);
    s.time.now = now - startNow;
    lastNow = now;
    s.events.length = 0;
    if (!updateAll(input, s)) return;

    accumulator += s.time.frameDt;
    let ticks = 0;
    while (accumulator >= DT && ticks < MAX_TICKS_PER_FRAME) {
      s.time.tick += 1;
      if (!updateAll(tick, s)) return;
      accumulator -= DT;
      ticks += 1;
    }
    if (ticks === MAX_TICKS_PER_FRAME) accumulator = 0;
    s.time.alpha = accumulator * 60;

    updateAll(frame, s);
  }

  function initAll(s: GameState): boolean {
    return all.every((system) =>
      guard(system, 'init', () => {
        system.init(s, host);
      }),
    );
  }

  function updateAll(systems: System[], s: GameState): boolean {
    return systems.every(
      (system) =>
        running &&
        guard(system, 'tick', () => {
          system.update(s);
        }),
    );
  }

  /** Runs one system call; on a throw, fails fast (Code §4.7) and returns false. */
  function guard(system: System, what: 'init' | 'tick' | 'dispose', call: () => void): boolean {
    try {
      call();
      return true;
    } catch (err) {
      const where = what === 'tick' ? `tick ${String(state?.time.tick ?? 0)}` : what;
      host.log.error(`[system ${system.name}] ${where}`, err);
      stop();
      host.display.showError(
        `ERROR IN ${system.name} — see console`,
        err instanceof Error ? err.message : String(err),
      );
      return false;
    }
  }

  return { start, stop };
}
