/*
System:   tickInput                 Phase: tick
Job:      Turn held actions and latched presses into this tick's player intent, applying
          directional flight (Design §9.5, §9.6, Impl §6.5).
Reads:    input.held, input.latched, world.ship.facing
Writes:   input.tick, input.latched
Emits:    —
Consumes: —
Guard:    simRunning
*/
import { sign } from '../../core/math';
import { simRunning } from '../../model/queries';
import type { System } from '../../scheduler/system';

/** Directional flight engages beyond this horizontal deflection (Design §9.5). */
const DIRECTIONAL_THRESHOLD = 0.35;

export function createTickInput(): System {
  return {
    name: 'tickInput',
    phase: 'tick',
    init() {
      // No platform resources.
    },
    update(state) {
      if (!simRunning(state)) return;
      const { held, latched, tick } = state.input;
      const directional = Math.abs(held.horizontal) > DIRECTIONAL_THRESHOLD;
      const against = directional && sign(held.horizontal) !== state.world.ship.facing;

      tick.vertical = held.vertical;
      tick.thrust = held.thrust || directional;
      tick.reverse = latched.reverse || against;
      tick.fire = latched.fire;
      tick.fireHeld = held.fire;
      tick.smartBomb = latched.smartBomb;
      tick.hyperspace = latched.hyperspace;

      // Each press reaches exactly one tick (Design §9.6).
      latched.reverse = false;
      latched.fire = false;
      latched.smartBomb = false;
      latched.hyperspace = false;
    },
    dispose() {
      // Nothing to release.
    },
  };
}
