import '@fontsource/orbitron/400.css';
import '@fontsource/orbitron/700.css';
import { createBrowserHost } from './host/host';
import { createInitialState } from './model/create';
import { FRAME_SYSTEMS, INPUT_SYSTEMS, TICK_SYSTEMS } from './scheduler/registry';
import { createScheduler } from './scheduler/scheduler';

// Boot (Impl §9.3).
const canvas = document.getElementById('game');
if (!(canvas instanceof HTMLCanvasElement)) throw new Error('main: no <canvas id="game">');
const host = createBrowserHost(canvas);
const state = createInitialState();
const scheduler = createScheduler(host, {
  input: INPUT_SYSTEMS,
  tick: TICK_SYSTEMS,
  frame: FRAME_SYSTEMS,
});
scheduler.start(state);
