/*
System:   keyboard                  Phase: input
Job:      Read the physical keyboard into its device state (Impl §6.1).
Reads:    settings.keyBindings
Writes:   input.devices.keyboard.down, input.devices.keyboard.pressed
Emits:    —
Consumes: —
Guard:    none (always runs)
*/
import { DEV_CODES, FIXED_CODES } from '../../config/keys';
import type { KeyEventTarget, Host } from '../../host/host';
import type { GameState } from '../../model/state/gameState';
import type { System } from '../../scheduler/system';

export function createKeyboard(): System {
  let target: KeyEventTarget | null = null;
  const down = new Set<string>();
  let pressed: string[] = [];
  /** Codes whose browser default is suppressed: bound, fixed, and dev keys. */
  let suppressed = new Set<string>();

  function onKeyDown(e: KeyboardEvent) {
    if (suppressed.has(e.code)) e.preventDefault();
    if (e.repeat) return;
    down.add(e.code);
    pressed.push(e.code);
  }

  function onKeyUp(e: KeyboardEvent) {
    if (suppressed.has(e.code)) e.preventDefault();
    down.delete(e.code);
  }

  function onBlur() {
    down.clear();
  }

  function refreshSuppressed(state: GameState) {
    suppressed = new Set<string>([
      ...FIXED_CODES,
      ...(import.meta.env.DEV ? DEV_CODES : []),
      ...Object.values(state.settings.keyBindings)
        .flat()
        .filter((code) => code !== null),
    ]);
  }

  return {
    name: 'keyboard',
    phase: 'input',
    init(state: GameState, host: Host) {
      down.clear();
      pressed = [];
      refreshSuppressed(state);
      target = host.inputs.window;
      target.addEventListener('keydown', onKeyDown);
      target.addEventListener('keyup', onKeyUp);
      target.addEventListener('blur', onBlur);
    },
    update(state) {
      refreshSuppressed(state);
      const keyboard = state.input.devices.keyboard;
      keyboard.down = new Set(down);
      keyboard.pressed = pressed;
      pressed = [];
    },
    dispose() {
      target?.removeEventListener('keydown', onKeyDown);
      target?.removeEventListener('keyup', onKeyUp);
      target?.removeEventListener('blur', onBlur);
      target = null;
    },
  };
}
