/*
System:   renderTerrain             Phase: frame
Job:      Draw the terrain: the `terrain` sprite at its actual size, tiled horizontally along the
          bottom of the playfield (Design §10.4, Impl §5.4).
Reads:    world.planetAlive, world.camera, fx.shake, time.alpha
Writes:   — (draws on display.scene)
Emits:    —
Consumes: —
Guard:    world exists and the planet is alive
*/
import { HUD_HEIGHT, PLAYFIELD_HEIGHT, SCREEN_W } from '../../config/constants';
import { SPRITES } from '../../config/sprites';
import type { Display } from '../../host/display';
import type { SpriteAtlas } from '../../host/sprites';
import { cameraXAt } from '../../model/queries';
import type { System } from '../../scheduler/system';

const TILE = SPRITES.terrain;
/** The tiles sit on the bottom of the playfield. */
const BOTTOM = HUD_HEIGHT + PLAYFIELD_HEIGHT;
/** Tiles needed to span the screen at any offset, plus one to cover the shake offset. */
const TILES = Math.ceil(SCREEN_W / TILE.w) + 2;

export function createRenderTerrain(): System {
  let display: Display | null = null;
  let sprites: SpriteAtlas | null = null;

  return {
    name: 'renderTerrain',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
      sprites = host.sprites;
    },
    update(state) {
      const { world } = state;
      if (!display || !sprites || !world?.planetAlive) return;
      const ctx = display.scene;
      const cam = cameraXAt(world, state.time.alpha);

      // Tile edges snap to device pixels, so neighbouring tiles share an exact pixel edge. A
      // fractional edge is antialiased in both tiles, and the backdrop shows through the seam.
      const { scale } = display;
      const snap = (v: number) => Math.round(v * scale) / scale;
      const top = snap(BOTTOM - TILE.h + state.fx.shake.y);
      const bottom = snap(BOTTOM + state.fx.shake.y);

      // Tiles repeat every TILE.w px from world x = 0; k starts at −1 to cover the shake offset.
      const offset = -(((cam % TILE.w) + TILE.w) % TILE.w) + state.fx.shake.x;
      for (let k = -1; k < TILES - 1; k++) {
        const left = snap(offset + k * TILE.w);
        const right = snap(offset + (k + 1) * TILE.w);
        sprites.draw(ctx, 'terrain', 0, (left + right) / 2, (top + bottom) / 2, {
          width: right - left,
          height: bottom - top,
        });
      }
    },
    dispose() {
      display = null;
      sprites = null;
    },
  };
}
