/** Bindable player actions, in display order (Design §9.1). */
export const ACTIONS = [
  'climb',
  'dive',
  'left',
  'right',
  'fire',
  'smartBomb',
  'hyperspace',
  'pause',
  'mute',
] as const;

export type Action = (typeof ACTIONS)[number];

/** Default key codes per action slot (Design §9.1, Impl §6.1). Pause slot 1 is locked (Design §9.2). */
export const DEFAULT_KEY_BINDINGS: Readonly<
  Record<Action, readonly [string | null, string | null]>
> = {
  climb: ['KeyW', 'ArrowUp'],
  dive: ['KeyS', 'ArrowDown'],
  left: ['ArrowLeft', null],
  right: ['ArrowRight', null],
  fire: ['KeyZ', 'Space'],
  smartBomb: ['KeyX', null],
  hyperspace: ['KeyC', null],
  pause: ['Escape', 'KeyP'],
  mute: ['KeyM', null],
};

/** Keys with fixed menu meanings, never rebindable (Design §8.2, §9.1; Impl §6.1). */
export const FIXED_CODES = [
  'Enter',
  'Escape',
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'Space',
  'Backspace',
  'Delete',
] as const;

/** Development keys: F3 overlay, F4–F8 cheats, F9 sprite gallery (Impl §10). */
export const DEV_CODES = ['F3', 'F4', 'F5', 'F6', 'F7', 'F8', 'F9'] as const;
