/*
System:   camera                    Phase: tick
Job:      Ease the camera anchor toward the ship's facing side and place the camera (Design §4.5).
Reads:    world.ship.x, world.ship.facing, world.camera.anchor, world.camera.anchorVel
Writes:   world.camera.anchor, world.camera.anchorVel, world.camera.x
Emits:    —
Consumes: —
Guard:    simActive
*/
import { CAMERA, DT } from '../../config/constants';
import { clamp, wrapX } from '../../core/math';
import { simActive } from '../../model/queries';
import { cameraTarget } from '../../model/worldOps';
import type { System } from '../../scheduler/system';

export function createCamera(): System {
  return {
    name: 'camera',
    phase: 'tick',
    init() {
      // No platform resources.
    },
    update(state) {
      if (!simActive(state)) return;
      const { camera, ship } = state.world;
      const gap = cameraTarget(ship) - camera.anchor;
      const dir = Math.sign(gap);

      // The fastest speed that can still brake to a stop at the target, up to the top speed. The
      // velocity changes toward it by at most the acceleration, so pans speed up and slow down
      // smoothly, and a mid-pan reverse brakes before heading back. Braking from u px/tick by c
      // px/tick each tick covers about u²/2c + u/2 px; solving that for the gap gives the speed.
      const { anchorSpeed, anchorAccel } = CAMERA;
      const maxChange = anchorAccel * DT;
      const c = maxChange * DT;
      const brakeSpeed = (c * (Math.sqrt(0.25 + (2 * Math.abs(gap)) / c) - 0.5)) / DT;
      const wanted = dir * Math.min(anchorSpeed, brakeSpeed);
      camera.anchorVel += clamp(wanted - camera.anchorVel, -maxChange, maxChange);
      camera.anchor += camera.anchorVel * DT;

      // Reaching or passing the target stops there.
      if (dir === 0 || Math.sign(cameraTarget(ship) - camera.anchor) !== dir) {
        camera.anchor = cameraTarget(ship);
        camera.anchorVel = 0;
      }
      camera.x = wrapX(ship.x - camera.anchor);
    },
    dispose() {
      // Nothing to release.
    },
  };
}
