/*
System:   present                   Phase: frame
Job:      Show the scene letterboxed on the main canvas (Design §3.3, Impl §5.3).
Reads:    —
Writes:   — (draws on display.main)
Emits:    —
Consumes: —
Guard:    none (always runs)
*/
import { PALETTE } from '../../config/palette';
import type { Display } from '../../host/display';
import type { System } from '../../scheduler/system';

export function createPresent(): System {
  let display: Display | null = null;

  return {
    name: 'present',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
    },
    update() {
      if (!display) return;
      const { main, scene, offsetX, offsetY } = display;
      main.setTransform(1, 0, 0, 1, 0, 0);
      main.fillStyle = PALETTE.background;
      main.fillRect(0, 0, main.canvas.width, main.canvas.height);
      main.drawImage(scene.canvas, offsetX, offsetY);
    },
    dispose() {
      display = null;
    },
  };
}
