/*
System:   renderStars               Phase: frame
Job:      Draw the twinkling parallax star field (Design §10.4).
Reads:    world.camera, app.screen, app.attractPage, fx.shake, time.alpha, time.now
Writes:   — (draws on display.scene)
Emits:    —
Consumes: —
Guard:    world exists, or the attract title page is shown
*/
import { HUD_HEIGHT, SCREEN_W, STARS } from '../../config/constants';
import { PALETTE } from '../../config/palette';
import { WORLD_WIDTH } from '../../core/math';
import { next, random } from '../../core/random';
import type { Display } from '../../host/display';
import { backgroundCameraX } from '../../model/queries';
import type { System } from '../../scheduler/system';

/** Stars repeat every W/2 px of parallax-scrolled screen. */
const FIELD_W = WORLD_WIDTH / 2;

interface Star {
  x: number;
  y: number;
  size: number;
  phase: number;
}

/** The fixed star field, identical every session (Impl §5.3): a private generator, not `rng`. */
function createStarField(): Star[] {
  const rng = { s: STARS.seed };
  return Array.from({ length: STARS.count }, () => ({
    x: random(rng, 0, FIELD_W),
    y: random(rng, 0, STARS.maxY),
    size: random(rng, STARS.minSize, STARS.maxSize),
    phase: next(rng) * Math.PI * 2,
  }));
}

export function createRenderStars(): System {
  let display: Display | null = null;
  let stars: Star[] = [];

  return {
    name: 'renderStars',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
      stars = createStarField();
    },
    update(state) {
      const cam = backgroundCameraX(state);
      if (!display || cam === null) return;
      const ctx = display.scene;
      const t = state.time.now;
      ctx.save();
      ctx.translate(state.fx.shake.x, state.fx.shake.y);
      ctx.fillStyle = PALETTE.star;
      for (const star of stars) {
        const sx = (((star.x - cam * STARS.parallax) % FIELD_W) + FIELD_W) % FIELD_W;
        if (sx >= SCREEN_W) continue;
        ctx.globalAlpha = 0.4 + 0.4 * Math.sin(t * 2 + star.phase);
        ctx.fillRect(sx - star.size / 2, HUD_HEIGHT + star.y - star.size / 2, star.size, star.size);
      }
      ctx.restore();
    },
    dispose() {
      display = null;
      stars = [];
    },
  };
}
