import { SPRITE_HITBOXES } from './hitboxes';

/**
 * One sprite of the art set (Design §10.3.1, Impl §5.9).
 * - `w`, `h`: the frame's drawn size, in logical px.
 * - `srcW`, `srcH`: one frame's size in the image, in image px. The image is `(frames × srcW) × srcH`.
 * - `hitbox`: the sprite is collidable, so its hitbox is measured from the art (`config/hitboxes.ts`).
 */
export interface SpriteSpec {
  readonly w: number;
  readonly h: number;
  readonly frames: number;
  readonly srcW: number;
  readonly srcH: number;
  readonly hitbox: boolean;
}

/** The art set, in catalog order (Design §10.3.1). Files: `assets/sprites/<Name>.png`. */
export const SPRITES = {
  ship: { w: 64, h: 64, frames: 1, srcW: 128, srcH: 128, hitbox: true },
  shipFlame: { w: 28, h: 28, frames: 1, srcW: 128, srcH: 128, hitbox: false },
  lander: { w: 40, h: 40, frames: 1, srcW: 128, srcH: 128, hitbox: true },
  mutant: { w: 40, h: 40, frames: 1, srcW: 128, srcH: 128, hitbox: true },
  bomber: { w: 32, h: 32, frames: 1, srcW: 128, srcH: 128, hitbox: true },
  pod: { w: 32, h: 32, frames: 8, srcW: 128, srcH: 128, hitbox: true },
  swarmer: { w: 20, h: 20, frames: 1, srcW: 128, srcH: 128, hitbox: true },
  baiter: { w: 56, h: 56, frames: 1, srcW: 128, srcH: 128, hitbox: true },
  humanoid: { w: 24, h: 24, frames: 1, srcW: 128, srcH: 128, hitbox: true },
  laser: { w: 400, h: 8, frames: 5, srcW: 800, srcH: 16, hitbox: true },
  bullet: { w: 16, h: 16, frames: 1, srcW: 128, srcH: 128, hitbox: true },
  mine: { w: 12, h: 12, frames: 1, srcW: 128, srcH: 128, hitbox: true },
  backdrop: { w: 1920, h: 920, frames: 1, srcW: 1920, srcH: 920, hitbox: false },
  terrain: { w: 960, h: 330, frames: 1, srcW: 960, srcH: 330, hitbox: false },
} as const satisfies Record<string, SpriteSpec>;

export type SpriteName = keyof typeof SPRITES;

/** The collidable sprites: those with a measured hitbox. */
export type HitboxSprite = keyof typeof SPRITE_HITBOXES;

/** A box relative to a sprite frame: offset of its top-left corner from the frame's, and size. */
export interface Box {
  readonly x: number;
  readonly y: number;
  readonly w: number;
  readonly h: number;
}

/** Each collidable sprite's hitbox in logical px, relative to the unmirrored frame (Design §2). */
export const HITBOXES = Object.fromEntries(
  Object.entries(SPRITE_HITBOXES).map(([name, box]) => {
    const { w, h, srcW, srcH } = SPRITES[name as HitboxSprite];
    const sx = w / srcW;
    const sy = h / srcH;
    return [name, { x: box.x * sx, y: box.y * sy, w: box.w * sx, h: box.h * sy }];
  }),
) as Record<HitboxSprite, Box>;
