/*
System:   renderMenus               Phase: frame
Job:      Draw the menu and attract screens (Design §8.3, §13.3).
Reads:    app.screen
Writes:   — (draws on display.scene)
Emits:    —
Consumes: —
Guard:    app.screen != 'playing'
*/
import { PALETTE } from '../../config/palette';
import type { Display } from '../../host/display';
import type { System } from '../../scheduler/system';

/** Horizontal center of the logical screen (Design §8.3: text is centered). */
const CENTER_X = 960;

export function createRenderMenus(): System {
  let display: Display | null = null;

  return {
    name: 'renderMenus',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
    },
    update(state) {
      if (!display || state.app.screen === 'playing') return;
      const ctx = display.scene;
      ctx.save();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      switch (state.app.screen) {
        case 'boot':
          // Design §13.3.
          ctx.font = '700 48px Orbitron, sans-serif';
          ctx.fillStyle = PALETTE.hudText;
          ctx.fillText('LOADING…', CENTER_X, 540);
          break;
        case 'attract':
          // Interim placeholder title (Plan M02), replaced by the attract pages in M23.
          ctx.font = '700 140px Orbitron, sans-serif';
          ctx.fillStyle = PALETTE.title;
          ctx.strokeStyle = PALETTE.titleOutline;
          ctx.lineWidth = 3;
          ctx.fillText('AI DEFENDER', CENTER_X, 380);
          ctx.strokeText('AI DEFENDER', CENTER_X, 380);
          break;
        default:
          break;
      }
      ctx.restore();
    },
    dispose() {
      display = null;
    },
  };
}
