/*
System:   shipFlight                Phase: tick
Job:      Fly the ship: reverse, thrust, drag, vertical movement, and wrap (Design §5.2); ease the
          drawn turn toward the facing (Design §10.3.3); count down invulnerability (Design §5.8).
Reads:    input.tick, world.ship
Writes:   world.ship.x, world.ship.y, world.ship.vx, world.ship.vy, world.ship.facing,
          world.ship.turn, world.ship.thrusting, world.ship.invulnerableTicks
Emits:    —
Consumes: —
Guard:    simActive
*/
import { DT, SHIP } from '../../config/constants';
import { clamp, wrapX } from '../../core/math';
import { simActive } from '../../model/queries';
import type { System } from '../../scheduler/system';

export function createShipFlight(): System {
  return {
    name: 'shipFlight',
    phase: 'tick',
    init() {
      // No platform resources.
    },
    update(state) {
      if (!simActive(state)) return;
      const { ship } = state.world;
      // The ship ignores input while in hyperspace (Design §5.2).
      const ignoring = ship.hyperspaceTicks > 0;
      const input = state.input.tick;
      const thrust = !ignoring && input.thrust;
      const vertical = ignoring ? 0 : input.vertical;

      // Reverse flips facing at once; vx carries on (Design §5.2).
      if (!ignoring && input.reverse) ship.facing = ship.facing === 1 ? -1 : 1;
      // Only the drawing turns gradually; the flight follows the new facing at once.
      const turnStep = 2 / SHIP.turnTicks;
      ship.turn = clamp(ship.turn + clamp(ship.facing - ship.turn, -turnStep, turnStep), -1, 1);
      if (Math.abs(ship.facing - ship.turn) < 1e-9) ship.turn = ship.facing;

      ship.thrusting = thrust;
      if (thrust) ship.vx += ship.facing * SHIP.thrust * DT;
      ship.vx -= ship.vx * SHIP.drag * DT;
      ship.vx = clamp(ship.vx, -SHIP.maxSpeed, SHIP.maxSpeed);
      if (!thrust && Math.abs(ship.vx) < SHIP.stopSpeed) ship.vx = 0;

      ship.vy = clamp(vertical, -1, 1) * SHIP.verticalSpeed;
      ship.y = clamp(ship.y + ship.vy * DT, SHIP.minY, SHIP.maxY);
      ship.x = wrapX(ship.x + ship.vx * DT);

      if (ship.invulnerableTicks > 0) ship.invulnerableTicks -= 1;
    },
    dispose() {
      // Nothing to release.
    },
  };
}
