/** The logical screen (Design §3.1). */
const LOGICAL_W = 1920;
const LOGICAL_H = 1080;

/** Highest device pixel ratio rendered at (Design §3.3). */
const MAX_DPR = 2;

/** Drawing surfaces, letterboxed to 16:9 (Impl §5.2). */
export interface Display {
  /** The visible canvas, in device pixels. */
  readonly main: CanvasRenderingContext2D;
  /** The offscreen scene, transformed so render systems draw in logical px. */
  readonly scene: CanvasRenderingContext2D;
  /** Device pixels per logical px. */
  readonly scale: number;
  /** Where the scene sits on the main canvas, in device pixels. */
  readonly offsetX: number;
  readonly offsetY: number;
  /** Converts client (CSS) coordinates to logical px. */
  toLogical(clientX: number, clientY: number): { x: number; y: number };
  /** Calls `cb` after every resize; returns the unsubscribe function. */
  onResize(cb: () => void): () => void;
  /** Replaces everything with a plain-text error: the title, and the message below it (Impl §3.5). */
  showError(title: string, message?: string): void;
}

export function createDisplay(canvas: HTMLCanvasElement): Display {
  const main = context2d(canvas);
  const scene = context2d(document.createElement('canvas'));
  const listeners = new Set<() => void>();
  let dpr = 1;

  const display = {
    main,
    scene,
    scale: 1,
    offsetX: 0,
    offsetY: 0,
    toLogical: (clientX: number, clientY: number) => ({
      x: (clientX * dpr - display.offsetX) / display.scale,
      y: (clientY * dpr - display.offsetY) / display.scale,
    }),
    onResize: (cb: () => void) => {
      listeners.add(cb);
      return () => {
        listeners.delete(cb);
      };
    },
    showError: (title: string, message?: string) => {
      const { width, height } = canvas;
      const size = Math.round(24 * dpr);
      const lines = message === undefined ? [title] : [title, message];
      main.setTransform(1, 0, 0, 1, 0, 0);
      main.fillStyle = '#000';
      main.fillRect(0, 0, width, height);
      main.fillStyle = '#FFF';
      main.font = `${String(size)}px sans-serif`;
      main.textAlign = 'center';
      main.textBaseline = 'middle';
      lines.forEach((line, i) => {
        main.fillText(line, width / 2, height / 2 + (i - (lines.length - 1) / 2) * size * 1.5);
      });
    },
  };

  function resize() {
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    canvas.width = Math.round(rect.width * dpr);
    canvas.height = Math.round(rect.height * dpr);
    const scale = Math.min(rect.width / LOGICAL_W, rect.height / LOGICAL_H) * dpr;
    display.scale = scale;
    display.offsetX = (canvas.width - LOGICAL_W * scale) / 2;
    display.offsetY = (canvas.height - LOGICAL_H * scale) / 2;
    scene.canvas.width = Math.round(LOGICAL_W * scale);
    scene.canvas.height = Math.round(LOGICAL_H * scale);
    scene.setTransform(scale, 0, 0, scale, 0, 0);
    // Sprites scale smoothly, never blocky (Design §10.1). Resizing resets these.
    scene.imageSmoothingEnabled = true;
    scene.imageSmoothingQuality = 'high';
    for (const cb of listeners) cb();
  }

  window.addEventListener('resize', resize);
  window.addEventListener('orientationchange', resize);
  window.visualViewport?.addEventListener('resize', resize);
  resize();
  return display;
}

function context2d(canvas: HTMLCanvasElement): CanvasRenderingContext2D {
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('display: no 2D canvas context');
  return ctx;
}
