/**
 * Every system, per phase, in execution order (Code §8.1, Impl §3.6). Adding or removing a
 * system is one line here. Dev-only systems are included only in development builds.
 */
import { createBoot } from '../systems/app/boot';
import { createCheats } from '../systems/dev/cheats';
import { createSpriteGallery } from '../systems/dev/spriteGallery';
import { createInputMapper } from '../systems/input/inputMapper';
import { createKeyboard } from '../systems/input/keyboard';
import { createTickInput } from '../systems/input/tickInput';
import { createPresent } from '../systems/render/present';
import { createRenderBackdrop } from '../systems/render/renderBackdrop';
import { createRenderClear } from '../systems/render/renderClear';
import { createRenderDebug } from '../systems/render/renderDebug';
import { createRenderEntities } from '../systems/render/renderEntities';
import { createRenderMenus } from '../systems/render/renderMenus';
import { createRenderStars } from '../systems/render/renderStars';
import { createRenderTerrain } from '../systems/render/renderTerrain';
import { createCamera } from '../systems/sim/camera';
import { createShipFlight } from '../systems/sim/shipFlight';
import { createWorldClock } from '../systems/sim/worldClock';
import type { SystemFactory } from './system';

// Each dev entry tests `import.meta.env.DEV` inline, so production builds drop the system's code.
const DEV = import.meta.env.DEV;

export const INPUT_SYSTEMS: readonly SystemFactory[] = [createKeyboard, createInputMapper];

export const TICK_SYSTEMS: readonly SystemFactory[] = [
  createTickInput,
  createWorldClock,
  createShipFlight,
  createCamera,
];

export const FRAME_SYSTEMS: readonly SystemFactory[] = [
  // App
  createBoot,
  // Dev
  ...(DEV ? [createCheats] : []),
  // Render layers
  createRenderClear,
  createRenderBackdrop,
  createRenderStars,
  createRenderTerrain,
  createRenderEntities,
  createRenderMenus,
  ...(DEV ? [createSpriteGallery] : []),
  ...(DEV ? [createRenderDebug] : []),
  createPresent,
];
