/*
System:   renderClear               Phase: frame
Job:      Clear the scene to the background color (Design §10.1 step 1, Impl §5.3).
Reads:    —
Writes:   — (draws on display.scene)
Emits:    —
Consumes: —
Guard:    none (always runs)
*/
import { PALETTE } from '../../config/palette';
import type { Display } from '../../host/display';
import type { System } from '../../scheduler/system';

export function createRenderClear(): System {
  let display: Display | null = null;

  return {
    name: 'renderClear',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
    },
    update() {
      if (!display) return;
      const ctx = display.scene;
      ctx.fillStyle = PALETTE.background;
      ctx.fillRect(0, 0, 1920, 1080);
    },
    dispose() {
      display = null;
    },
  };
}
