/*
System:   spriteGallery             Phase: frame
Job:      Draw the F9 sprite gallery: every sprite's frames, measured hitboxes, and a live preview
          (Impl §10, Design §10.3).
Reads:    app.dev.gallery, app.platform.spritesReady, time.now
Writes:   — (draws on display.scene)
Emits:    —
Consumes: —
Guard:    app.dev.gallery and app.platform.spritesReady
*/
import { FLAME } from '../../config/constants';
import { PALETTE } from '../../config/palette';
import { HITBOXES, SPRITES, type HitboxSprite, type SpriteName } from '../../config/sprites';
import type { Display } from '../../host/display';
import type { SpriteAtlas } from '../../host/sprites';
import { flameWidth } from '../../model/queries';
import type { System } from '../../scheduler/system';

/** The sprites shown in the grid of small cells, in catalog order. */
const SMALL: readonly SpriteName[] = (Object.keys(SPRITES) as SpriteName[]).filter(
  (name) => name !== 'laser' && name !== 'backdrop' && name !== 'terrain',
);
const CELL_W = 320;
const CELL_H = 240;
const PER_ROW = 6;
const GRID_TOP = 60;
const LASER_TOP = 540;
const TILES_TOP = 740;
/** Frame views are drawn at 2× (Impl §10). */
const ZOOM = 2;
const FRAME_GAP = 8;

const hasHitbox = (name: SpriteName): name is HitboxSprite => name in HITBOXES;

/** The width of a sprite's frames side by side at 2×. */
const framesWidth = (name: SpriteName) => {
  const { w, frames } = SPRITES[name];
  return frames * w * ZOOM + (frames - 1) * FRAME_GAP;
};

interface Cell {
  name: SpriteName;
  /** Top-left corner, and how many cells wide. */
  x: number;
  y: number;
  span: number;
}

/**
 * Places the small sprites in catalog order, each in the first free run of cells wide enough
 * for its frames and its preview, so a many-frame sprite (the pod) spans several cells.
 */
function layoutCells(): Cell[] {
  const taken: boolean[][] = [];
  const free = (row: number, col: number, span: number) =>
    Array.from({ length: span }, (_, k) => !taken[row]?.[col + k]).every(Boolean);
  return SMALL.map((name) => {
    // Margin, frames, gap, the preview, margin; single cells keep their preview at x + 250.
    const needed = 16 + framesWidth(name) + 16 + SPRITES[name].w + 8;
    const span = Math.min(PER_ROW, Math.ceil(needed / CELL_W));
    for (let row = 0; ; row++) {
      for (let col = 0; col + span <= PER_ROW; col++) {
        if (!free(row, col, span)) continue;
        taken[row] ??= [];
        for (let k = 0; k < span; k++) (taken[row] ?? [])[col + k] = true;
        return { name, x: col * CELL_W, y: GRID_TOP + row * CELL_H, span };
      }
    }
  });
}

const CELLS = layoutCells();
const randomIn = (lo: number, hi: number) => lo + Math.random() * (hi - lo);

export function createSpriteGallery(): System {
  let display: Display | null = null;
  let sprites: SpriteAtlas | null = null;

  /** One frame at `zoom`, with its bounds in gray and its hitbox in red; (x, y) is its top-left. */
  function frameView(
    ctx: CanvasRenderingContext2D,
    name: SpriteName,
    frame: number,
    x: number,
    y: number,
    zoom: number,
  ) {
    const { w, h } = SPRITES[name];
    sprites?.draw(ctx, name, frame, x + (w * zoom) / 2, y + (h * zoom) / 2, { scale: zoom });
    ctx.strokeStyle = '#666';
    ctx.strokeRect(x, y, w * zoom, h * zoom);
    if (hasHitbox(name)) {
      const box = HITBOXES[name];
      ctx.strokeStyle = '#F00';
      ctx.strokeRect(x + box.x * zoom, y + box.y * zoom, box.w * zoom, box.h * zoom);
    }
  }

  /** The 1× preview centered on (x, y), animated per Design §10.3.3 in real time. */
  function preview(
    ctx: CanvasRenderingContext2D,
    name: SpriteName,
    x: number,
    y: number,
    t: number,
  ) {
    if (!sprites) return;
    switch (name) {
      case 'ship': {
        const width = flameWidth(t);
        sprites.draw(ctx, 'shipFlame', 0, x + FLAME.offsetX - width / 2, y + FLAME.offsetY, {
          width,
          height: FLAME.height,
        });
        sprites.draw(ctx, 'ship', 0, x, y);
        break;
      }
      case 'shipFlame':
        sprites.draw(ctx, name, 0, x, y, { width: flameWidth(t), height: FLAME.height });
        break;
      case 'mutant':
        sprites.draw(ctx, name, 0, x + randomIn(-2, 2), y + randomIn(-2, 2));
        break;
      case 'bomber':
        sprites.draw(ctx, name, 0, x, y, { rotation: t });
        break;
      case 'pod':
        sprites.draw(ctx, name, 0, x, y, { rotation: t * 2 });
        break;
      case 'mine':
        sprites.draw(ctx, name, 0, x, y, { rotation: t * 4 });
        break;
      case 'bullet':
        sprites.draw(ctx, name, 0, x, y, { alpha: randomIn(0.7, 1) });
        break;
      default:
        sprites.draw(ctx, name, 0, x, y);
    }
  }

  function label(ctx: CanvasRenderingContext2D, text: string, x: number, y: number) {
    ctx.fillStyle = PALETTE.hudText;
    ctx.fillText(text, x, y);
  }

  return {
    name: 'spriteGallery',
    phase: 'frame',
    init(_state, host) {
      display = host.display;
      sprites = host.sprites;
    },
    update(state) {
      if (!display || !sprites || !state.app.dev.gallery || !state.app.platform.spritesReady)
        return;
      const ctx = display.scene;
      const t = state.time.now;
      ctx.save();
      ctx.fillStyle = PALETTE.background;
      ctx.fillRect(0, 0, 1920, 1080);
      ctx.font = '20px monospace';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.lineWidth = 1;
      label(ctx, 'SPRITE GALLERY (F9): frames at 2×, hitboxes in red, live previews at 1×', 16, 30);

      for (const { name, x: cx, y: cy, span } of CELLS) {
        const { w, h, frames } = SPRITES[name];
        label(ctx, name, cx + 16, cy + 20);
        for (let f = 0; f < frames; f++)
          frameView(ctx, name, f, cx + 16 + f * (w * ZOOM + FRAME_GAP), cy + 44, ZOOM);
        const previewX = span === 1 ? cx + 250 : cx + 16 + framesWidth(name) + 16 + w / 2;
        preview(ctx, name, previewX, cy + 44 + (h * ZOOM) / 2, t);
      }

      // The laser: frames stacked, and a preview growing from 0 to 400 px every second.
      const laser = SPRITES.laser;
      label(ctx, 'laser', 16, LASER_TOP + 20);
      for (let f = 0; f < laser.frames; f++)
        frameView(ctx, 'laser', f, 16, LASER_TOP + 40 + f * (laser.h * ZOOM + FRAME_GAP), ZOOM);
      const length = (t % 1) * laser.w;
      if (length > 0) {
        const head = 1400;
        sprites.draw(
          ctx,
          'laser',
          Math.floor(t) % laser.frames,
          head - length / 2,
          LASER_TOP + 100,
          {
            cropLeft: laser.w - length,
          },
        );
      }

      // Backdrop and terrain: two copies side by side, so a seam would show.
      (['backdrop', 'terrain'] as const).forEach((name, i) => {
        const cx = i * 960;
        const { w, h } = SPRITES[name];
        const scale = Math.min(928 / (2 * w), 290 / h);
        label(ctx, name, cx + 16, TILES_TOP + 20);
        for (let k = 0; k < 2; k++)
          sprites?.draw(
            ctx,
            name,
            0,
            cx + 16 + (k + 0.5) * w * scale,
            TILES_TOP + 40 + (h * scale) / 2,
            { scale },
          );
      });
      ctx.restore();
    },
    dispose() {
      display = null;
      sprites = null;
    },
  };
}
