/** How long to wait for the game font before going on without it (Design §13.3). */
const FONT_TIMEOUT_MS = 3000;

/** Browser services that aren't drawing or input (Impl §3.4). */
export interface Platform {
  fonts: {
    /** Resolves when the bold game font has loaded, or after 3 s (Impl §5.8). Never rejects. */
    ready(): Promise<void>;
  };
  /** The value of the page URL's query parameter `name`, or null (Impl §10). */
  query(name: string): string | null;
}

export function createBrowserPlatform(): Platform {
  return {
    fonts: {
      ready: () =>
        Promise.race([
          document.fonts.load('700 48px Orbitron').then(
            () => undefined,
            () => undefined,
          ),
          new Promise<void>((resolve) => setTimeout(resolve, FONT_TIMEOUT_MS)),
        ]),
    },
    query: (name) => new URLSearchParams(window.location.search).get(name),
  };
}
